/**
 * Tool-surface coverage — loads the 309 baseline tool records (generated by
 * `import:baseline-tools`) and validates set completeness/disposition (plan §14.1).
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

export const TOOL_DISPOSITIONS = ['planned', 'migrated', 'retired', 'quarantined'] as const;
export type ToolDisposition = (typeof TOOL_DISPOSITIONS)[number];

export interface ToolSurfaceRecord {
  toolId: string;
  category: string;
  durationClass: string;
  destructive: boolean;
  acceptsAbortSignal: boolean | null;
  forwardsAbortSignal: boolean | null;
  implementationFile: string;
  usedByAgentCount: number;
  effectClass: string | null;
  disposition: ToolDisposition;
  wave: string | null;
}

export interface ToolSurfacesDoc {
  schemaVersion: string;
  source: string;
  count: number;
  records: ToolSurfaceRecord[];
}

export function loadToolSurfaces(): ToolSurfacesDoc {
  const path = resolve(dirname(fileURLToPath(import.meta.url)), 'tool-surfaces.json');
  return JSON.parse(readFileSync(path, 'utf8')) as ToolSurfacesDoc;
}

export interface ToolIssue { level: 'error' | 'warn'; message: string }

/** Validate the tool set: exact count, no duplicates, valid dispositions. */
export function validateToolSurfaces(doc: ToolSurfacesDoc, expectedCount = 309): ToolIssue[] {
  const issues: ToolIssue[] = [];
  if (doc.records.length !== doc.count) issues.push({ level: 'error', message: `count field ${doc.count} != records ${doc.records.length}` });
  if (doc.records.length !== expectedCount) issues.push({ level: 'error', message: `expected ${expectedCount} tool surfaces, got ${doc.records.length}` });

  const seen = new Set<string>();
  for (const r of doc.records) {
    if (seen.has(r.toolId)) issues.push({ level: 'error', message: `duplicate toolId: ${r.toolId}` });
    seen.add(r.toolId);
    if (!(TOOL_DISPOSITIONS as readonly string[]).includes(r.disposition)) {
      issues.push({ level: 'error', message: `${r.toolId}: invalid disposition ${r.disposition}` });
    }
    // A migrated tool needs an assigned effectClass and wave (§14.1).
    if (r.disposition === 'migrated' && (!r.effectClass || !r.wave)) {
      issues.push({ level: 'error', message: `${r.toolId}: migrated but missing effectClass/wave` });
    }
  }
  return issues;
}

export function summarizeToolSurfaces(doc: ToolSurfacesDoc): {
  byCategory: Record<string, number>;
  byDisposition: Record<string, number>;
  destructive: number;
  acceptsAbortTrue: number;
} {
  const byCategory: Record<string, number> = {};
  const byDisposition: Record<string, number> = {};
  let destructive = 0, acceptsAbortTrue = 0;
  for (const r of doc.records) {
    byCategory[r.category] = (byCategory[r.category] ?? 0) + 1;
    byDisposition[r.disposition] = (byDisposition[r.disposition] ?? 0) + 1;
    if (r.destructive) destructive++;
    if (r.acceptsAbortSignal === true) acceptsAbortTrue++;
  }
  return { byCategory, byDisposition, destructive, acceptsAbortTrue };
}
